// Generated by AI (UnitTest MCP)
//! Lodestar MCP — an MCP (Model Context Protocol) server over stdio that exposes
//! the Intent Plane (durable constitution, task coordination, conformance, and
//! consolidated knowledge) to coding agents.

mod server;
mod tools;

use lodestar_core::Lodestar;
use mindleak_session::SessionRegistry;
use mindleak_storage::{resolve_database, resolve_workspace_path, DatabaseKind};

fn main() -> anyhow::Result<()> {
    let current = std::env::current_dir().unwrap_or_else(|_| ".".into());
    let workspace = resolve_workspace_path(
        &current,
        std::env::var("MINDLEAK_WORKSPACE").ok().as_deref(),
    );
    let database = resolve_database(
        &workspace,
        DatabaseKind::Lodestar,
        std::env::var("LODESTAR_DB").ok().as_deref(),
    )?;
    let migrated_legacy = database.migrate_legacy_if_needed()?;
    database.ensure_parent()?;
    let storage_status = database.status("lodestar", migrated_legacy);
    let db_path = database.path.to_string_lossy().into_owned();
    // Display name for this process's sessions in reports. Since ADR-0054 it
    // is no part of the agent id, so two processes may disagree about it
    // without forking the identity of a session they both host.
    let display_name = std::env::var("LODESTAR_AGENT").unwrap_or_else(|_| "agent".to_string());
    let sessions = SessionRegistry::new(&display_name).map_err(anyhow::Error::msg)?;
    let engine = Lodestar::open(&db_path)?;
    eprintln!(
        "[lodestar-mcp] ready — intent plane at {db_path}; repository_id={}; origin={:?}; migrated_legacy={migrated_legacy}",
        database.repository_id.as_deref().unwrap_or("none"),
        database.origin,
    );
    server::run(engine, sessions, storage_status)
}

#[cfg(test)]
mod tests {
    use std::fs;
    use std::path::{Path, PathBuf};
    use std::process::Command;
    use std::sync::atomic::{AtomicUsize, Ordering};

    use mindleak_storage::{resolve_database_in, DatabaseKind, DatabaseOrigin};

    static NEXT_SANDBOX: AtomicUsize = AtomicUsize::new(0);

    fn sandbox(name: &str) -> PathBuf {
        let ordinal = NEXT_SANDBOX.fetch_add(1, Ordering::Relaxed);
        let path = std::env::temp_dir().join(format!(
            "lodestar-mcp-storage-{name}-{}-{ordinal}",
            std::process::id()
        ));
        let _ = fs::remove_dir_all(&path);
        fs::create_dir_all(&path).unwrap();
        path
    }

    fn git(cwd: &Path, args: &[&str]) {
        let mut command = Command::new("git");
        for variable in [
            "GIT_DIR",
            "GIT_WORK_TREE",
            "GIT_COMMON_DIR",
            "GIT_INDEX_FILE",
            "GIT_OBJECT_DIRECTORY",
            "GIT_ALTERNATE_OBJECT_DIRECTORIES",
        ] {
            command.env_remove(variable);
        }
        let output = command
            .args(args)
            .current_dir(cwd)
            .env("PRE_COMMIT_ALLOW_NO_CONFIG", "1")
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "git {args:?}: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    fn repository(root: &Path) -> PathBuf {
        let repository = root.join("repo");
        fs::create_dir_all(&repository).unwrap();
        git(&repository, &["init", "-b", "main"]);
        git(&repository, &["config", "user.name", "Lodestar Test"]);
        git(
            &repository,
            &["config", "user.email", "lodestar@example.invalid"],
        );
        fs::write(repository.join("README.md"), "test\n").unwrap();
        git(&repository, &["add", "README.md"]);
        git(&repository, &["commit", "-m", "initial"]);
        repository
    }

    #[test]
    fn lodestar_db_override_wins_over_git_and_cwd() {
        let got = resolve_database_in(
            Path::new("/repo/worktree"),
            DatabaseKind::Lodestar,
            Some("/custom/plane.db"),
            Path::new("/state"),
        )
        .unwrap();
        assert_eq!(got.path, PathBuf::from("/custom/plane.db"));
        assert_eq!(got.origin, DatabaseOrigin::Explicit);
    }

    #[test]
    fn a_blank_override_is_ignored() {
        let scratch = sandbox("blank");
        let got = resolve_database_in(
            &scratch,
            DatabaseKind::Lodestar,
            Some("   "),
            &scratch.join("state"),
        )
        .unwrap();
        assert_eq!(got.path, scratch.join(".lodestar").join("spec.db"));
        fs::remove_dir_all(scratch).unwrap();
    }

    #[test]
    fn worktrees_of_one_repo_share_a_single_plane() {
        let root = sandbox("worktrees");
        let repository = repository(&root);
        let linked = root.join("linked");
        git(
            &repository,
            &["worktree", "add", "-b", "feature", linked.to_str().unwrap()],
        );
        let state_root = root.join("state");
        let main =
            resolve_database_in(&repository, DatabaseKind::Lodestar, None, &state_root).unwrap();
        let worktree =
            resolve_database_in(&linked, DatabaseKind::Lodestar, None, &state_root).unwrap();
        assert_eq!(main.repository_id, worktree.repository_id);
        assert_eq!(main.path, worktree.path);
        assert!(main.path.ends_with("spec.db"));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn falls_back_to_cwd_outside_a_git_repo() {
        let scratch = sandbox("fallback");
        let got = resolve_database_in(
            &scratch,
            DatabaseKind::Lodestar,
            None,
            &scratch.join("state"),
        )
        .unwrap();
        assert_eq!(got.path, scratch.join(".lodestar").join("spec.db"));
        assert_eq!(got.origin, DatabaseOrigin::Workspace);
        fs::remove_dir_all(scratch).unwrap();
    }
}
